CREATE OR REPLACE FUNCTION public.public_form_finalize_submission(p_form_id uuid, p_submission_id uuid, p_queja_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE v_submission public.public_form_submissions%ROWTYPE; v_folio text;
BEGIN
 SELECT s.* INTO v_submission FROM public.public_form_submissions s WHERE s.form_id = p_form_id AND s.submission_id = p_submission_id AND s.queja_id = p_queja_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'PUBLIC_SUBMISSION_UNAVAILABLE'; END IF;
 SELECT folio INTO STRICT v_folio FROM public.quejas WHERE id = p_queja_id;
 IF v_submission.finalized_at IS NOT NULL THEN RETURN jsonb_build_object('folio',v_folio,'finalized',true); END IF;
 PERFORM 1 FROM public.formularios_publicos WHERE id = p_form_id AND activo AND modulo = 'quejas' FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'PUBLIC_FORM_UNAVAILABLE'; END IF;
 IF EXISTS (SELECT 1 FROM public.public_form_uploads WHERE form_id = p_form_id AND submission_id = p_submission_id AND status = 'reserved') THEN
 RAISE EXCEPTION USING ERRCODE = '23505', MESSAGE = 'PUBLIC_UPLOAD_PENDING';
 END IF;
 -- Marca y notificaciones/mail_queue se confirman juntas bajo el mismo lock.
 PERFORM public.notificar_queja_publica(v_folio);
 UPDATE public.public_form_submissions SET finalized_at = now() WHERE form_id = p_form_id AND submission_id = p_submission_id;
 RETURN jsonb_build_object('folio',v_folio,'finalized',true);
END;
$function$

CREATE OR REPLACE FUNCTION public.qms_mail_claim_batch_v2(p_limit integer, p_lease_seconds integer, p_run_nonce uuid, p_issued_at bigint)
 RETURNS TABLE(id uuid, claim_token uuid, tipo text, destinatario text, folio text, estado text, numero_oficio text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE inserted integer; moment bigint:=floor(extract(epoch FROM now()))::bigint;
BEGIN
 IF p_limit IS NULL OR p_limit NOT BETWEEN 0 AND 5 OR p_lease_seconds IS NULL OR p_lease_seconds NOT BETWEEN 60 AND 600
 OR p_run_nonce IS NULL OR p_issued_at IS NULL OR p_issued_at<moment-300 OR p_issued_at>moment+30 THEN
 RAISE EXCEPTION 'Solicitud de worker inválida.' USING ERRCODE='22023';
 END IF;
 DELETE FROM public.queja_mail_run_nonces WHERE nonce IN
 (SELECT n.nonce FROM public.queja_mail_run_nonces n WHERE n.expires_at<now() ORDER BY n.expires_at LIMIT 1000);
 INSERT INTO public.queja_mail_run_nonces VALUES(p_run_nonce,now()+interval '10 minutes') ON CONFLICT(nonce) DO NOTHING;
 GET DIAGNOSTICS inserted=ROW_COUNT;
 IF inserted=0 THEN RETURN; END IF;
 PERFORM public.qms_process_notices();
 -- Sin cuota/diario de MailApp el poll sigue produciendo campanas, sin reservar envíos.
 IF p_limit=0 THEN RETURN; END IF;
 -- Nunca se reenvía una reserva incierta, tampoco si el destinatario ya cambió.
 UPDATE public.queja_mail_outbox SET status='uncertain',safe_error='lease_expired',updated_at=now()
 WHERE status='leased' AND lease_until<=now();
 UPDATE public.queja_mail_outbox SET status='failed',safe_error='attempt_limit',updated_at=now()
 WHERE status IN ('pending','retry') AND attempts>=12;
 UPDATE public.queja_mail_outbox o SET status='skipped',safe_error='obsolete_notice',updated_at=now()
 WHERE o.tipo LIKE 'interno_%' AND o.status IN ('pending','retry')
 AND NOT public.qms_internal_delivery_eligible(o.id);
 RETURN QUERY WITH candidates AS (
 SELECT o.id FROM public.queja_mail_outbox o WHERE o.status IN ('pending','retry')
 AND o.next_attempt_at<=now() AND o.attempts<12
 AND (o.tipo LIKE 'interno_%' OR NOT EXISTS (
 SELECT 1 FROM public.queja_mail_outbox prior WHERE prior.queja_id=o.queja_id
 AND prior.tipo IN ('recibido','investigacion','final') AND prior.status<>'sent'
 AND CASE prior.tipo WHEN 'recibido' THEN 1 WHEN 'investigacion' THEN 2 ELSE 3 END
 < CASE o.tipo WHEN 'recibido' THEN 1 WHEN 'investigacion' THEN 2 ELSE 3 END))
 ORDER BY o.next_attempt_at,o.id LIMIT p_limit FOR UPDATE SKIP LOCKED
 ), claimed AS (
 UPDATE public.queja_mail_outbox o SET status='leased',claim_token=gen_random_uuid(),
 lease_until=now()+make_interval(secs=>p_lease_seconds),attempts=o.attempts+1,updated_at=now()
 FROM candidates c WHERE o.id=c.id RETURNING o.*
 ) SELECT c.id,c.claim_token,c.tipo,c.destinatario,c.folio,c.estado,c.numero_oficio FROM claimed c;
END;
$function$

CREATE OR REPLACE FUNCTION public.qms_transition_complaint(p_id uuid, p_expected bigint, p_state text, p_resolution text DEFAULT NULL::text, p_justification text DEFAULT NULL::text, p_owner uuid DEFAULT NULL::uuid, p_reopen text DEFAULT NULL::text, p_office_number text DEFAULT NULL::text, p_resolution_format text DEFAULT NULL::text, p_justification_format text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE q public.quejas; own_revision bigint; office text; staff boolean;
BEGIN
 SELECT * INTO q FROM public.quejas WHERE id = p_id FOR UPDATE;
 staff := coalesce(public.app_es_admin(), false)
 OR (coalesce(public.app_es_staff(), false) AND coalesce(public.app_tiene_permiso('quejas', true), false));
 IF auth.uid() IS NULL OR NOT (staff OR (coalesce(public.app_es_colaborador(), false)
 AND coalesce(public.app_tiene_permiso('mis_quejas', true), false)
 AND coalesce(q.responsable_id = public.app_usuario_actual_id(), false))) THEN
 RAISE EXCEPTION 'No autorizado.' USING ERRCODE = '42501';
 END IF;
 IF q.id IS NULL THEN RAISE EXCEPTION 'Queja no encontrada.' USING ERRCODE = 'P0002'; END IF;
 IF p_expected IS NULL OR q.revision IS DISTINCT FROM p_expected THEN
 RAISE EXCEPTION 'Otra persona modificó la queja. Actualiza antes de guardar.' USING ERRCODE = '40001';
 END IF;
 IF NOT EXISTS (SELECT 1 FROM public.catalogos WHERE modulo = 'quejas' AND tipo = 'estado_queja'
 AND codigo = p_state AND coalesce(activo, true)) THEN
 RAISE EXCEPTION 'Estado no reconocido.' USING ERRCODE = '22023';
 END IF;
 IF p_resolution_format IS NOT NULL AND (p_resolution IS NULL OR p_resolution_format NOT IN ('plain','markdown'))
 OR p_justification_format IS NOT NULL AND (p_justification IS NULL OR p_justification_format NOT IN ('plain','markdown'))
 OR length(coalesce(p_resolution, '')) > 10000 OR length(coalesce(p_justification, '')) > 10000
 OR length(coalesce(p_reopen, '')) > 10000 THEN
 RAISE EXCEPTION 'Texto o formato inválido.' USING ERRCODE = '22023';
 END IF;
 office := coalesce(nullif(btrim(p_office_number), ''), q.numero_oficio_resolucion);
 IF length(office) > 120 OR (p_state IN ('rejected','resolved','finished') AND office IS NULL) THEN
 RAISE EXCEPTION 'La respuesta final necesita un número de oficio válido.' USING ERRCODE = '22023';
 END IF;
 IF p_owner IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.usuarios WHERE id = p_owner AND estado = 'activo') THEN
 RAISE EXCEPTION 'Seleccioná un responsable activo.' USING ERRCODE = '22023';
 END IF;
 -- Se valida la revisión original ANTES de nuestra escritura bajo el mismo lock.
 -- La revisión enviada al motor es exclusivamente la producida por esta operación.
 UPDATE public.quejas SET numero_oficio_resolucion = office,
 resolucion_formato = CASE WHEN p_resolution IS NULL THEN resolucion_formato ELSE coalesce(p_resolution_format, 'plain') END,
 justificacion_procede = CASE WHEN p_justification IS NULL THEN justificacion_procede ELSE nullif(btrim(p_justification), '') END,
 justificacion_procede_formato = CASE WHEN p_justification IS NULL THEN justificacion_procede_formato ELSE coalesce(p_justification_format, 'plain') END
 WHERE id = p_id RETURNING revision INTO own_revision;
 PERFORM public.qms_transition(p_id, own_revision, p_state, p_resolution, p_justification, p_owner, p_reopen);
 RETURN (SELECT to_jsonb(v) FROM public.qms_quejas v WHERE v.id = p_id);
END;
$function$

CREATE OR REPLACE FUNCTION public.registrar_adjunto_queja_servidor(p_actor_id uuid, p_queja_id uuid, p_nombre text, p_storage_path text, p_tamano bigint, p_tipo_mime text)
 RETURNS queja_adjuntos
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE
 v_actor public.usuarios;
 v_queja public.quejas;
 v_adjunto public.queja_adjuntos;
 v_nombre text := btrim(coalesce(p_nombre, ''));
 v_path text := btrim(coalesce(p_storage_path, ''));
 v_mime text := btrim(coalesce(p_tipo_mime, ''));
 v_count bigint;
 v_bytes bigint;
 v_reserved_count bigint;
 v_reserved_bytes bigint;
BEGIN
 -- Mantiene rol/actividad mientras se confirma: un evento Auth tardío no puede elevar actor.
 SELECT * INTO v_actor FROM public.usuarios
 WHERE id = p_actor_id AND estado = 'activo' AND auth_id IS NOT NULL
 FOR SHARE;
 IF NOT FOUND THEN
 RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'DRIVE_ATTACHMENT_FORBIDDEN';
 END IF;

 -- Comparte el lock del expediente con el gateway público antes de contar su cuota.
 SELECT * INTO v_queja FROM public.quejas WHERE id = p_queja_id FOR UPDATE;
 IF NOT FOUND OR NOT (
 v_actor.rol IN ('admin', 'calidad')
 OR (v_actor.rol = 'colaborador' AND v_queja.responsable_id IS NOT DISTINCT FROM v_actor.id)
 ) THEN
 RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'DRIVE_ATTACHMENT_FORBIDDEN';
 END IF;

 IF char_length(v_nombre) NOT BETWEEN 1 AND 255
 OR v_nombre ~ '[[:cntrl:]/\\]'
 OR v_path !~ '^[A-Za-z0-9_-]{10,200}$'
 OR p_tamano IS NULL OR p_tamano NOT BETWEEN 1 AND 4194304
 OR char_length(v_mime) NOT BETWEEN 3 AND 127
 OR v_mime !~ '^[A-Za-z0-9][A-Za-z0-9.+_-]*/[A-Za-z0-9][A-Za-z0-9.+_-]*$'
 THEN
 RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'DRIVE_ATTACHMENT_INVALID';
 END IF;

 -- Con respuesta perdida, confirmar el mismo archivo retorna la misma fila y no repite auditoría.
 SELECT * INTO v_adjunto FROM public.queja_adjuntos
 WHERE queja_id = p_queja_id AND storage_path = v_path
 ORDER BY created_at, id LIMIT 1;
 IF FOUND THEN
 IF v_adjunto.usuario_id IS DISTINCT FROM p_actor_id
 OR v_adjunto.nombre IS DISTINCT FROM v_nombre
 OR v_adjunto.tamano IS DISTINCT FROM p_tamano
 OR v_adjunto.tipo_mime IS DISTINCT FROM v_mime
 THEN
 RAISE EXCEPTION USING ERRCODE = '23505', MESSAGE = 'DRIVE_ATTACHMENT_CONFLICT';
 END IF;
 RETURN v_adjunto;
 END IF;

 SELECT count(*), coalesce(sum(greatest(coalesce(tamano, 0), 0)), 0)
 INTO v_count, v_bytes FROM public.queja_adjuntos WHERE queja_id = p_queja_id;
 SELECT count(*), coalesce(sum(u.tamano), 0)
 INTO v_reserved_count, v_reserved_bytes
 FROM public.public_form_submissions s
 JOIN public.public_form_uploads u
 ON u.form_id = s.form_id AND u.submission_id = s.submission_id
 WHERE s.queja_id = p_queja_id AND u.status = 'reserved';
 IF v_count + v_reserved_count >= 10
 OR v_bytes + v_reserved_bytes + p_tamano > 41943040
 THEN
 RAISE EXCEPTION USING ERRCODE = '54000', MESSAGE = 'DRIVE_ATTACHMENT_QUOTA';
 END IF;

 INSERT INTO public.queja_adjuntos (
 queja_id, nombre, nombre_archivo, storage_path, url_archivo,
 tamano, tipo_mime, usuario_id, created_at
 ) VALUES (
 p_queja_id, v_nombre, v_nombre, v_path, v_path,
 p_tamano::integer, v_mime, p_actor_id, now()
 ) RETURNING * INTO v_adjunto;
 INSERT INTO public.logs (fecha, usuario_id, accion, modulo, detalle)
 VALUES (now(), p_actor_id, 'adjunto', 'quejas',
 'Adjunto registrado por servidor en la queja ' || p_queja_id);
 RETURN v_adjunto;
END;
$function$
